:root {
  --ink: #243842;
  --paper: #fffdf5;
  --sky: #dff3f5;
  --line: #8dbfc4;
}

.wind-note {
  box-sizing: border-box;
  width: 420px;
  padding: 16px;
  background: var(--paper);
  border: 2px solid var(--line);
  border-radius: 14px;
}

.wind-note header {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 12px;
}

.glyph {
  font-size: 28px;
  line-height: 1;
}

.wind-note h2 {
  margin: 0;
  color: var(--ink);
  font-size: 19px;
  line-height: 1.2;
}

.wind-data {
  display: flex;
  justify-content: space-between;
  padding: 10px 12px;
  background: var(--sky);
  border-radius: 8px;
  color: var(--ink);
  font-size: 14px;
}

.wind-data strong {
  font-weight: 700;
}
